fn solve(n: i8, s: Vec<char>) -> i8 {
    // We assume n >= 1 and s.len() == n as usize.
    let mut count: i8 = 0;
    let len = n as usize;
    // Iterate over all indices 0..len-1 (exclusive of the last index)
    for i in 0..len.saturating_sub(1) {
        if s[i] == s[i + 1] {
            count += 1;
        }
    }
    count
}

